   501	func v2FullRefsFetchTarget(ctx context.Context, repoRoot string) string {
   502		target, err := remote.FetchURL(ctx, remote.FetchURLOptions{WorktreeRoot: repoRoot})
   503		if err == nil && target != "" {
   504			return target
   505		}
   506		return "origin"
   507	}
