   535	// readTranscriptFromRef reads the raw transcript from a specific /full/* ref.
   536	// Follows the same chunking convention as readTranscriptFromTree in committed.go:
   537	// chunk 0 is the base file (raw_transcript), chunks 1+ are raw_transcript.001, .002, etc.
   538	// When chunk files exist, all chunks (including chunk 0) are reassembled using
   539	// agent-aware reassembly via agent.ReassembleTranscript.
   540	func (s *V2GitStore) readTranscriptFromRef(refName plumbing.ReferenceName, sessionPath string, agentType types.AgentType) ([]byte, error) {
   541		_, rootTreeHash, err := s.GetRefState(refName)
   542		if err != nil {
