   647				return 0, nil, nil, fmt.Errorf("failed to read session %d metadata: %w", i, err)
   648			}
   649			totalCount += meta.CheckpointsCount
   650			allFiles = mergeFilesTouched(allFiles, meta.FilesTouched)
   651			totalTokens = aggregateTokenUsage(totalTokens, meta.TokenUsage)
   652		}
   653	
   654		return totalCount, allFiles, totalTokens, nil
   655	}
