   664	// readJSONFromBlob reads JSON from a blob hash and decodes it to the given type.
   665	func readJSONFromBlob[T any](repo *git.Repository, hash plumbing.Hash) (*T, error) {
   666		blob, err := repo.BlobObject(hash)
   667		if err != nil {
   668			return nil, fmt.Errorf("failed to get blob: %w", err)
   669		}
   670	
   671		reader, err := blob.Reader()
   672		if err != nil {
   673			return nil, fmt.Errorf("failed to get blob reader: %w", err)
   674		}
   675		defer reader.Close()
   676	
   677		var result T
   678		if err := json.NewDecoder(reader).Decode(&result); err != nil {
   679			return nil, fmt.Errorf("failed to decode: %w", err)
   680		}
   681	
   682		return &result, nil
   683	}
