   698			result.InputTokens = a.InputTokens
   699			result.CacheCreationTokens = a.CacheCreationTokens
   700			result.CacheReadTokens = a.CacheReadTokens
   701			result.OutputTokens = a.OutputTokens
   702			result.APICallCount = a.APICallCount
   703		}
   704		if b != nil {
