   706			result.CacheCreationTokens += b.CacheCreationTokens
   707			result.CacheReadTokens += b.CacheReadTokens
   708			result.OutputTokens += b.OutputTokens
   709			result.APICallCount += b.APICallCount
   710		}
   711		return result
   712	}
