   933	// ReadCommitted reads a committed checkpoint's summary by ID from the entire/checkpoints/v1 branch.
   934	// Returns only the CheckpointSummary (paths + aggregated stats), not actual content.
   935	// Use ReadSessionContent to read actual transcript/prompts/context.
   936	// Returns nil, nil if the checkpoint doesn't exist.
   937	//
   938	// The storage format uses numbered subdirectories for each session (0-based):
   939	//
   940	//	<checkpoint-id>/
   941	//	├── metadata.json      # CheckpointSummary with sessions map
   942	//	├── 0/                 # First session
   943	//	│   ├── metadata.json  # Session-specific metadata
   944	//	│   └── full.jsonl     # Transcript
   945	//	├── 1/                 # Second session
   946	//	└── ...
   947	func (s *GitStore) ReadCommitted(ctx context.Context, checkpointID id.CheckpointID) (*CheckpointSummary, error) {
   948		if err := ctx.Err(); err != nil {
   949			return nil, err //nolint:wrapcheck // Propagating context cancellation
   950		}
   951	
   952		ft, err := s.getFetchingTree(ctx)
   953		if err != nil {
   954			return nil, nil //nolint:nilnil,nilerr // No sessions branch means no checkpoint exists
   955		}
   956	
   957		checkpointPath := checkpointID.Path()
   958		checkpointTree, err := ft.Tree(checkpointPath)
   959		if err != nil {
   960			return nil, nil //nolint:nilnil,nilerr // Checkpoint directory not found
   961		}
   962	
   963		// Read root metadata.json as CheckpointSummary (auto-fetches blob if needed)
   964		metadataFile, err := checkpointTree.File(paths.MetadataFileName)
   965		if err != nil {
   966			return nil, nil //nolint:nilnil,nilerr // metadata.json not found
   967		}
   968	
   969		content, err := metadataFile.Contents()
   970		if err != nil {
   971			return nil, fmt.Errorf("failed to read metadata.json: %w", err)
   972		}
   973	
   974		var summary CheckpointSummary
   975		if err := json.Unmarshal([]byte(content), &summary); err != nil {
   976			return nil, fmt.Errorf("failed to parse metadata.json: %w", err)
   977		}
   978	
   979		return &summary, nil
   980	}
