   458		cmd.Dir = repoPath
   459		if err := cmd.Run(); err != nil {
   460			var exitErr *exec.ExitError
   461			if errors.As(err, &exitErr) && exitErr.ExitCode() == 1 {
   462				return true, nil // No common ancestor — disconnected
   463			}
